import{c as r,Q as t,j as a,m as o}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"新領域研究報告 2026-07-27：可溯源假說生成與自主科研協作基礎設施","description":"","frontmatter":{"date":"2026-07-27T00:00:00.000Z","archived_items":3,"dedup_verified":true,"domains":["hypothesis-generation-infrastructure"],"grounded_sources":[2607.00924,2606.30246,2605.06345],"source_routine":"routine-e","type":"new-domain-report"},"headers":[],"relativePath":"research/reports/2026-07-27-new-domain-hypothesis-generation-infrastructure.md","filePath":"research/reports/2026-07-27-new-domain-hypothesis-generation-infrastructure.md","lastUpdated":1785909234000}'),i={name:"research/reports/2026-07-27-new-domain-hypothesis-generation-infrastructure.md"};function n(s,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="新領域研究報告-2026-07-27-可溯源假說生成與自主科研協作基礎設施" tabindex="-1">新領域研究報告 2026-07-27：可溯源假說生成與自主科研協作基礎設施 <a class="header-anchor" href="#新領域研究報告-2026-07-27-可溯源假說生成與自主科研協作基礎設施" aria-label="Permalink to &quot;新領域研究報告 2026-07-27：可溯源假說生成與自主科研協作基礎設施&quot;">​</a></h1><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>本次探勘選定 1 個新領域：<strong>hypothesis-generation-infrastructure</strong>（可溯源假說生成與自主科研協作基礎設施）。三篇 90 天內全新 arxiv 論文從推理側、問題形成側、協作基礎設施側三個切面逼近同一個裁決性主張——AI 輔助科研的瓶頸已從「生成能力」移到「推導鏈與貢獻的可稽核性」。反回音室去重（正向+反向 grep）與接地（3 篇 arxiv 全數 WebFetch 直接讀取核對，含二次 citation-existence 覆核）皆已完成，核心關鍵詞命中數全數 ❤️，通過去重閘。</p><h2 id="為何是「新」領域-反回音室證明" tabindex="-1">為何是「新」領域（反回音室證明） <a class="header-anchor" href="#為何是「新」領域-反回音室證明" aria-label="Permalink to &quot;為何是「新」領域（反回音室證明）&quot;">​</a></h2><p>對候選核心關鍵詞執行 <code>grep -ic</code>，對 <code>/tmp/covered_topics.txt</code>（DAILY-TOPICS + WEEKLY-FOCUS + NEW-DOMAINS/covered_topics.txt 累積，414 terms）與 <code>/tmp/covered_paper_terms.txt</code>（既收錄論文標題高頻詞）兩個獨立集合合計檢查：</p><table tabindex="0"><thead><tr><th>關鍵詞</th><th>命中數</th><th>判定</th></tr></thead><tbody><tr><td>hypothesis</td><td>0</td><td>✅ 新</td></tr><tr><td>recombination</td><td>0</td><td>✅ 新</td></tr><tr><td>co-scientist</td><td>0</td><td>✅ 新</td></tr><tr><td>infrastructure</td><td>2</td><td>✅ 新（❤️）</td></tr><tr><td>hypothesis-generation-infrastructure（全 slug）</td><td>0</td><td>✅ 新</td></tr><tr><td>reasoning</td><td>1</td><td>✅ 新（背景詞，非本體詞）</td></tr><tr><td>agentic</td><td>9</td><td>回音室邊界詞——但為 workspace 自身研究對象的通用形容詞，非本領域本體詞；slug 命名已主動規避</td></tr><tr><td>verification</td><td>2</td><td>來自 2026-06-28 已收錄 formal-verification-robotics，驗證對象為機器人控制器安全性質，與本領域「科學推理鏈可溯源性」對象不同，同詞異指非重複覆蓋</td></tr></tbody></table><p>門檻：命中 ≥3 = 回音室內排除；本領域全數 ❤️，通過去重閘。與 <code>research/NEW-DOMAINS/INDEX.md</code> 既有 5 列（神經形態運算/形式驗證機器人、主動推論/機器遺忘、AI 主題湧現偵測/神經符號機器人策略、基因體生物基礎模型、代價感知算力分配/量子-古典機器學習）逐列概念比對，亦無重疊。</p><p>本輪選題判斷（候選篩選 + 領域取捨裁決 + 報告合成段落）委派 multi-mode-agent（model=opus, [mode: ceiling]）執行；main thread 事後親自重跑 <code>infrastructure</code> 補充 grep（agent 原僅驗證 <code>hypothesis</code>）+ 對 3 篇 arxiv 逐篇 WebFetch 核對標題與 URL 可達性，機械複驗其 verdict（sub-agent 裁定非證據，见 graph.md §G5）。</p><h2 id="領域概覽" tabindex="-1">領域概覽 <a class="header-anchor" href="#領域概覽" aria-label="Permalink to &quot;領域概覽&quot;">​</a></h2><h3 id="核心問題-範式" tabindex="-1">核心問題 / 範式 <a class="header-anchor" href="#核心問題-範式" aria-label="Permalink to &quot;核心問題 / 範式&quot;">​</a></h3><p>核心問題不是生出更多像樣的假說，而是假說的<strong>來源、推導鏈與貢獻歸屬可被第三方檢視與重放</strong>；三篇 90 天內新論文從三個切面逼近此事。</p><p><strong>推理側</strong>：Graph-PRefLexOR（<a href="https://arxiv.org/abs/2607.00924" target="_blank" rel="noreferrer">arXiv:2607.00924</a>，2026-07-01，Pal/Sourav/Ghosal/Buehler）將假說生成拆為機制探索、圖構建、模式提取、假說合成四階段，以 GRPO 訓練，使因果關係顯式建圖、可檢視可重用；材料科學與力學 100 道開放式問題上較 baseline 提升 40–65%，增益最大者為推理可溯源性而非答案本身。</p><p><strong>問題形成側</strong>：InciteResearch（<a href="https://arxiv.org/abs/2605.06345" target="_blank" rel="noreferrer">arXiv:2605.06345</a>，2026-05-07，Yu &amp; Qiu）處理「內隱摩擦」（問題尚無法明確表述前的錯位直覺）：五維研究者側寫、挑戰隱藏假設（feasibility×novelty 乘積優化＋七階段因果推導鏈）、驗證方法是否重框後洞見的必然結果，並提出 TF-Bench（novelty 3.671→4.250、impact 3.806→4.397）。</p><p><strong>基礎設施側</strong>：Clarus（<a href="https://arxiv.org/abs/2606.30246" target="_blank" rel="noreferrer">arXiv:2606.30246</a>，2026-06-29，Guo 等 18 位作者）主張現有工具是孤立助手而非協作平台，以四層架構（Research Application／Digital Collaboration／Physical Substrate／Physical World）協調人類研究者、團隊、實驗室、組織與 AI，使研究開放、可稽核、可歸因、資源感知。</p><h3 id="關鍵玩家-代表工作" tabindex="-1">關鍵玩家 / 代表工作 <a class="header-anchor" href="#關鍵玩家-代表工作" aria-label="Permalink to &quot;關鍵玩家 / 代表工作&quot;">​</a></h3><ul><li><strong>推理可溯源性</strong>：Pal, Sourav, Ghosal, Buehler（<a href="https://arxiv.org/abs/2607.00924" target="_blank" rel="noreferrer">arXiv:2607.00924</a>）——Graph-PRefLexOR。</li><li><strong>問題形成 / 內隱摩擦</strong>：Yu, Qiu（<a href="https://arxiv.org/abs/2605.06345" target="_blank" rel="noreferrer">arXiv:2605.06345</a>）——InciteResearch + TF-Bench。</li><li><strong>協作基礎設施</strong>：Guo 等 18 位共同作者（<a href="https://arxiv.org/abs/2606.30246" target="_blank" rel="noreferrer">arXiv:2606.30246</a>）——Clarus。</li></ul><h3 id="當前進展與開放問題" tabindex="-1">當前進展與開放問題 <a class="header-anchor" href="#當前進展與開放問題" aria-label="Permalink to &quot;當前進展與開放問題&quot;">​</a></h3><ul><li>① Graph-PRefLexOR：增加測試期算力主要買到「有界概念空間內的重組」而非語意知識擴張，若成立則 inference scaling 對真新穎性存在天花板，跨界擴張概念空間尚無解。</li><li>② novelty/impact 與 TF-Bench 多由 LLM 評分，oracle 自身資格未獨立驗證，存在循環性風險。</li><li>③ 可歸因與可稽核在含物理實驗、資源競爭的真實實驗室場景落地成本未知。</li><li>④ 三者僅在單一或少數學科（材料科學/力學、軟體研究、協作論文生成案例）驗證，跨學科泛化未證。</li></ul><h2 id="對本-workspace-的潛在槓桿" tabindex="-1">對本 workspace 的潛在槓桿 <a class="header-anchor" href="#對本-workspace-的潛在槓桿" aria-label="Permalink to &quot;對本 workspace 的潛在槓桿&quot;">​</a></h2><p>（以下均為候選方向，未經實作驗證，一律標「待驗證」；不自動改動 <code>.claude/</code>）</p><ul><li><strong>可歸因性（attribution）是否該與 Done-when 同級</strong>：Clarus 將「可歸因」列為與開放性、可稽核性並列的一等目標；workspace 的 Handoff Contract Return 欄位記錄驗證輸出，但無機讀「哪個節點對哪個結論負責」欄位。多節點合流後結論出錯，回溯責任節點成本多高、是否值得增欄——<strong>待驗證</strong>。</li><li><strong>顯式推導邊 vs 「verdict 非證據」</strong>：Graph-PRefLexOR 把因果關係從隱式推理外化成可檢視的圖。對應 graph.md §G5「parent 對 child verdict 須機械重驗」，若 child 回報附帶「從哪個 artifact 推到哪個結論」的邊，parent 重驗可有靶點而非整段重跑。其 token 成本是否低於重驗省下的成本——<strong>待驗證</strong>。</li><li><strong>test-time compute 天花板論是負面結論</strong>：若「增加算力主要提升有界概念空間內的重組」成立，則對缺 reference、缺 context 型任務升 effort／升檔位只會放大既有概念重組，不會補上缺失概念——與 core.md IDENTIFY「References &gt; 散文 spec」同向，但對升級判準是限制而非支持。單篇、單學科證據，<strong>待驗證</strong>。</li><li><strong>tacit friction ≈ Unknown Knowns</strong>：InciteResearch 的「內隱摩擦」與 know-your-unknowns SKILL 的 Unknown Knowns（說不清但認得出）幾乎同義；其五維側寫與「挑戰隱藏假設」流程是否構成 T1–T11 之外的可用 technique 候選——<strong>待驗證</strong>。</li><li><strong>「方法是否為重框後洞見的必然結果」作為自審問句</strong>：對自己方案做反向必然性檢查，形式接近 ceiling 檔位的 reverse-advisor 自審。是否比現行自審多帶來增益，或只是換句話說——<strong>待驗證</strong>。</li><li><strong>資源感知與經濟停損同帳本</strong>：Clarus 的 resource-aware 與 loop.md §L0「停損指標是每個被接受變更的成本」處理同一件事兩端（事前配額 vs 事後單位成本）。能否合成單一帳本、是否有實際量測管道——<strong>待驗證</strong>。</li><li><strong>本領域的評測循環性是既有條文的外部佐證，而非新條文</strong>：LLM 打自己分正是 loop.md §L4「Oracle 資格先於採信」所指；最可能用途是條文的 citation anchor，而非新增規則。是否值得入 refs——<strong>待驗證</strong>。</li><li><strong>反向警訊（誠實標注）</strong>：本領域詞彙（多參與者、協作、可稽核、可歸因）與 workspace 自身敘事高度同構，借鏡時極易退化為自我確認。若後續引入，優先取其與現行做法<strong>相衝突</strong>的主張（如 test-time compute 天花板論、評測循環性），而非相符的部分。</li></ul><h2 id="收錄來源" tabindex="-1">收錄來源 <a class="header-anchor" href="#收錄來源" aria-label="Permalink to &quot;收錄來源&quot;">​</a></h2><ul><li><code>research/papers/2026-07-27-graph-native-hypothesis-generation-2607-00924.md</code>（<a href="https://arxiv.org/abs/2607.00924" target="_blank" rel="noreferrer">arXiv:2607.00924</a>，submitted 2026-07-01，authors: Subhadeep Pal, Shashwat Sourav, Tirthankar Ghosal, Markus J. Buehler）</li><li><code>research/papers/2026-07-27-clarus-web-scale-scientific-collaboration-2606-30246.md</code>（<a href="https://arxiv.org/abs/2606.30246" target="_blank" rel="noreferrer">arXiv:2606.30246</a>，submitted 2026-06-29，authors: Zihan Guo, Zeyi Chen, Zhiyu Chen, Zicai Cui, Shuai Shao, Bo Huang, Zhi Han, Yuanyi Song, Yuan Yuan, Chenxi Zeng, Xiaohang Nie, Zhengxi Yu, Hanwen Zhu, Junwei Liao, Ming Zhou, Yang Li, Yuanjian Zhou, Weinan Zhang）</li><li><code>research/papers/2026-07-27-pre-question-scientific-ideation-2605-06345.md</code>（<a href="https://arxiv.org/abs/2605.06345" target="_blank" rel="noreferrer">arXiv:2605.06345</a>，submitted 2026-05-07，authors: Jie Yu, Song Qiu）</li></ul><h2 id="方法論註記-websearch-queries-used-verbatim" tabindex="-1">方法論註記（WebSearch queries used, verbatim） <a class="header-anchor" href="#方法論註記-websearch-queries-used-verbatim" aria-label="Permalink to &quot;方法論註記（WebSearch queries used, verbatim）&quot;">​</a></h2><ol><li><code>&quot;emerging AI research direction&quot; 2026 (NOT &quot;Claude&quot; NOT &quot;Anthropic&quot;)</code></li><li><code>arxiv new submissions trending 2026 site:arxiv.org (cs.AI OR cs.LG OR cs.RO)</code></li><li><code>&quot;underexplored&quot; OR &quot;open problem&quot; machine learning 2026</code></li><li><code>breakthrough 2026 (robotics OR &quot;world model&quot; OR &quot;formal verification&quot; OR neuromorphic OR bio-ML)</code></li><li><code>site:x.com researcher thread &quot;new paradigm&quot; OR &quot;we should be working on&quot; 2026</code></li></ol><p>第 5 組（X/Twitter 前沿信號）未產出可用、likes ≥500 或長文等級的一手推文來源，故本次收錄全為論文，符合 spec「推文或論文皆可」的彈性條款。</p><h2 id="後續追蹤建議" tabindex="-1">後續追蹤建議 <a class="header-anchor" href="#後續追蹤建議" aria-label="Permalink to &quot;後續追蹤建議&quot;">​</a></h2><ul><li>若 Graph-PRefLexOR 的「test-time compute 重組天花板」主張在後續論文中被獨立複現（非同作者群），值得升級為 WEEKLY-FOCUS 觀察項，並回頭檢視 loop.md 升級判準是否需要補一條「effort 升級對缺 reference 任務的邊際效益遞減」的告誡。</li><li>若 Clarus 或同類協作基礎設施論文後續釋出開源實作，可評估其「可歸因協作網路」設計是否有可直接借鏡的 schema，供 graph.md §G4 Handoff Contract 參考（仍需先過提案≠套用閘）。</li><li>下次 Routine E 執行前，此領域 slug（<code>hypothesis-generation-infrastructure</code>）已寫入去重持久化檔，後續探勘會自動避開。</li></ul>',28)])])}const p=r(i,[["render",n]]);export{g as __pageData,p as default};
